function makeItem(id,x,y,size){const c=byId[id];if(!c)throw Error('Unknown item');const item={uid:uid(),order:state.items.reduce((max,item,i)=>Math.max(max,item.order??i),-1)+1,id,x,y,size:Math.min(MAX_SIZE,Math.max(40,size||c.size)),flip:false,flipY:false,rotation:0};return item;}
function placeItem(id,x,y){if(!ready||busy)return false;if(!id){notify('Choose an item from a collection first.');return false;}if(state.items.length>=100){notify('There is no room for another oddity. Remove one, or start a new grove.');return false;}remember();const item=makeItem(id,x,y);state.items.push(item);activeUid=item.uid;render();return true;}
function addOddity(id){if(!byId[id])return;const d=dimensions({id,size:byId[id].size});if(placeItem(id,W/2,(H+d.h)/2)){notify(byId[id].name+' Added','success',true);if(isMobilePicker())returnToCanvas();}}
function copyActive(){const item=activeItem();if(!item||busy)return false;if(state.items.length>=100){notify('There is no room for another oddity. Remove one, or start a new grove.');return false;}remember();const d=dimensions(item),offset=Math.max(70,Math.min(150,item.size*.18)),cx=item.x,cy=item.y-d.h/2;const copy={...clone(item),uid:uid(),order:state.items.reduce((max,value,i)=>Math.max(max,value.order??i),-1)+1,x:Math.max(-MAX_SIZE,Math.min(W+MAX_SIZE,item.x+(cx>W*.72?-offset:offset))),y:Math.max(-MAX_SIZE,Math.min(H+MAX_SIZE,item.y+(cy>H*.72?-offset:offset)))};state.items.push(copy);activeUid=copy.uid;render();notify(byId[copy.id].name+' copied.','success');return true;}
async function loadFavorites(){showActivity('favorites','Loading favorite oddities…');try{const result=await request('/api/favorites');favorites=new Set(result.items.filter(id=>byId[id]));renderSprites();}catch{notify('Favorites could not sync. Your creations are still available.','error');}finally{hideActivity('favorites');}}
async function toggleFavorite(itemId){if(busy||favoritePending.has(itemId))return;if(!requireAccount('sync your favorite oddities'))return;favoritePending.add(itemId);showActivity('favorite-'+itemId,'Saving favorite oddity…');renderSprites();try{const result=await request('/api/favorites',{method:'POST',body:JSON.stringify({itemId,favorite:!favorites.has(itemId)})});if(!result.saved)throw Error('The favorite was not saved.');result.favorite?favorites.add(itemId):favorites.delete(itemId);notify(result.favorite?'Added to favorites.':'Removed from favorites.','success');}catch(e){notify(e.message,'error');}finally{favoritePending.delete(itemId);hideActivity('favorite-'+itemId);renderSprites();}}
const itemAliases={seal:'pinniped ocean marine mammal', 'red-panda':'red panda firefox lesser panda', 'giant-panda':'giant panda bear bamboo', 'grizzly-bear':'grizzly brown bear', 'polar-bear':'polar arctic bear',teeth:'fang tooth','corner-web':'cobweb messy tangled web',bunny:'rabbit',idol:'satanic demon devil sculpture',pentagram:'satanic occult pentacle',ritualcircle:'satanic occult sigil ritual',gnome:'gnomes goblin',alien:'aliens extraterrestrial',ufo:'aliens spaceship saucer',fairyring:'mushrooms faerie fairy ring',flytrap:'carnivorous venus flytrap','shooting-star':'meteor shooting stars',clouds:'cloud sky',tornado:'storm cyclone',waterbear:'tardigrade water bear',trex:'t-rex dinosaur',triceratops:'dinosaur',nessie:'nessie loch ness monster','poppy-seeds':'poppy seed pods',cannabis:'marijuana weed'};
const categoryTerms={creatures:'creature animal critter',plants:'plant botanical flower flora vegetation',mushrooms:'fungi fungus mushroom toadstool',nature:'nature natural outdoor landscape',bones:'bone skeleton skeletal remains anatomy',structures:'structure building architecture furniture',magic:'magic magical occult witch witchcraft ritual haunted',sky:'sky celestial astronomy cosmic space'};
const relatedTerms={
 bird:['owl','raven','falcon','phoenix','penguin'],cat:['cat','black-cat','sleeping-cat','stretching-cat','tuxedo-cat'],rabbit:['bunny','jackalope','rabbit-skull'],dinosaur:['trex','triceratops'],
 aquatic:['seal','dolphin','whale','manatee','octopus','squid','shrimp','starfish','nessie','kraken','coral','bubble','pond'],ocean:['seal','dolphin','whale','manatee','octopus','squid','shrimp','starfish','kraken','coral','bubble'],
 bug:['spider','web','orb-web','corner-web','mothman'],arachnid:['spider','web','orb-web','corner-web'],web:['web','orb-web','corner-web'],skull:['skull','rabbit-skull','deer-skull','wolf-skull','bird-skull'],
 flower:['rose','nightshade','lily','morning-glory','dandelion','poppy-seeds','clovers'],tree:['pine','sapling','stump','log','roots','vines'],
 storm:['clouds','tornado','lightning'],weather:['clouds','tornado','rainbow','lightning'],moon:['moon-full','moon-half','moon-crescent','moon-blood','lunar-eclipse','solar-eclipse'],galaxy:['galaxy-violet','galaxy-teal','galaxy-rose'],
 cryptid:['mothman','slender-man','chupacabra','bigfoot','jackalope','nessie'],mythical:['dragon','phoenix','unicorn','griffin','kraken','mothman','slender-man','chupacabra','bigfoot','jackalope','nessie'],
 fire:['flame','bonfire','candles','single-candle','lantern'],light:['flame','bonfire','candles','single-candle','lantern','sun','lightning'],pumpkin:['pumpkin','jack'],
 halloween:['pumpkin','jack','ghost','skull','bat','witch','cauldron','scarecrow','black-cat'],alien:['alien','ufo'],satanic:['pentagram','ritualcircle','idol'],human:['skull','ribs','skeletal-arm','skeletal-leg','skeletal-hips','skeletal-hand','skeletal-foot']
};
const irregularWords={fungi:'fungus',mice:'mouse',teeth:'tooth',leaves:'leaf',bunnies:'bunny',faerie:'fairy',faeries:'fairy',bugs:'bug',knives:'knife',wolves:'wolf',feet:'foot',witches:'witch',foxes:'fox',birds:'bird'};
function searchWords(text){return text.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,' ').trim().split(/\s+/).filter(Boolean).map(word=>irregularWords[word]||(/ies$/.test(word)?word.slice(0,-3)+'y':word.length>3&&word.endsWith('s')&&!word.endsWith('ss')?word.slice(0,-1):word));}
const searchIndex=new Map(catalog.map(item=>[item.id,new Set(searchWords([item.name,item.id,categoryTerms[item.group],item.group,itemAliases[item.id]||'',...Object.entries(relatedTerms).filter(([,ids])=>ids.includes(item.id)).map(([term])=>term),'oddity item'].join(' ')))]));
function matchesSearch(item,query){const words=searchIndex.get(item.id);return searchWords(query).every(term=>[...words].some(word=>word===term||word.startsWith(term)));}
function renderSprites(){syncCategoryPicker();const el=$('#stamps'),query=$('#itemSearch').value.trim().toLowerCase();const entries=catalog.filter(v=>!v.hidden&&(favoritesOnly?favorites.has(v.id):query||category==='all'?true:v.group===category)&&(!query||matchesSearch(v,query))).sort((a,b)=>a.name.localeCompare(b.name,undefined,{sensitivity:'base'}));el.classList.add('stamps');el.classList.toggle('many',entries.length>6);el.classList.toggle('search-results',!!query);el.replaceChildren();$('#favoriteFilter').setAttribute('aria-pressed',String(favoritesOnly));$('#favoriteFilter').setAttribute('aria-label',favoritesOnly?'Show All Oddities':'Show Favorite Oddities');$('#favoriteFilter').title=favoritesOnly?'Show All Oddities':'Show Favorite Oddities';$('#catalogCount').textContent=titleCaseLabel(favoritesOnly?entries.length+' favorite '+(entries.length===1?'item':'items'):query?entries.length+' '+(entries.length===1?'match':'matches')+' across the grove':entries.length+' '+({all:'oddities',mushrooms:'fungi',nature:'natural objects',magic:'magical objects',sky:'sky objects'}[category]||category));if(!entries.length){const p=document.createElement('p');p.className='search-empty';p.textContent=favoritesOnly?'Tap a heart on an oddity to keep it here.':'Nothing lurking by that name. Try another word.';el.append(p);return;}for(const item of entries){const card=document.createElement('div');card.className='stamp-card';card.dataset.id=item.id;const b=document.createElement('button');b.className='stamp';b.setAttribute('aria-label','Add '+item.name+' to the center');b.title='Add '+item.name;b.dataset.id=item.id;b.disabled=busy;const im=document.createElement('img');im.alt='';im.draggable=false;im.src=thumbs.get(item.id);b.append(im,document.createTextNode(item.name));b.addEventListener('click',()=>addOddity(item.id));const heart=document.createElement('button');heart.className='favorite-heart'+(signedIn===false?' requires-sign-in':'');heart.innerHTML=heartIcon;heart.setAttribute('aria-pressed',String(favorites.has(item.id)));heart.setAttribute('aria-label',(favorites.has(item.id)?'Remove ':'Add ')+item.name+(favorites.has(item.id)?' from favorites':' to favorites'));heart.disabled=busy||favoritePending.has(item.id);heart.addEventListener('click',()=>toggleFavorite(item.id));card.append(b,heart);el.append(card);}}
function drawSprite(target,id,x,y,size,flip=false,hue=0,flipY=false,filter='',rotation=0){const s=sprites.get(id);if(!s)return;const scale=size/Math.max(s.width,s.height),w=s.width*scale,h=s.height*scale;target.save();target.translate(x,y-h/2);target.rotate((rotation||0)*Math.PI/180);target.scale(flip?-1:1,flipY?-1:1);if(hue||filter)target.filter=[hue?`hue-rotate(${hue}deg)`:'',filter].filter(Boolean).join(' ');target.drawImage(s,-w/2,-h/2,w,h);target.restore();}
function blankColor(p){return '#'+p.bg.slice(1).match(/../g).map(v=>Math.round((parseInt(v,16)+255)/2).toString(16).padStart(2,'0')).join('');}
function draw(target,scene=state,time=0,still=true){const p=palettes[scene.palette]||palettes.haunted,r=rand(scene.seed);target.clearRect(0,0,W,H);target.save();target.fillStyle=scene.background==='void'?'#140e1c':scene.background==='none'?blankColor(p):p.bg;target.fillRect(0,0,W,H);const bg=scene.background==='void'?null:backgroundImages.get(scene.background);if(bg){const scale=Math.max(W/bg.width,H/bg.height);target.save();target.filter=[p.hue?`hue-rotate(${p.hue}deg)`:'',p.filter].filter(Boolean).join(' ')||'none';target.drawImage(bg,(W-bg.width*scale)/2,(H-bg.height*scale)/2,bg.width*scale,bg.height*scale);target.restore();if(p.tint){target.save();target.globalCompositeOperation='soft-light';target.globalAlpha=p.tintAlpha;target.fillStyle=p.tint;target.fillRect(0,0,W,H);target.restore();}}
if(scene.galaxy!=='none'){target.save();target.globalAlpha=.8;drawSprite(target,'galaxy-'+scene.galaxy,590,775,730,false,p.hue,false,p.filter);target.restore();}
if(scene.moon!=='none')drawSprite(target,'moon-'+scene.moon,990,250,155,false,p.hue,false,p.filter);
if(scene.weather.includes('lightning'))drawSprite(target,'lightning',235,280,240,false,p.hue,false,p.filter);
drawShootingStars(target,time,still,scene);
for(const item of scene.items){target.save();if(item.id==='shooting-star'&&!still&&!reducedMotion)target.globalAlpha=.77+.23*Math.sin(time/500+item.x/100);drawSprite(target,item.id,item.x,item.y,item.size,item.flip,p.hue,!!item.flipY,p.filter,item.rotation||0);target.restore();}
if(scene.weather.includes('rain')){target.save();target.lineCap='round';const drops=Array.from({length:290},()=>{const x=r()*W,y=r()*H,length=26+r()*25;return{x,y,length};});for(const pass of [{color:p.ink,width:5,alpha:.38},{color:scene.palette==='monochrome'?'#f5f5f5':'#f1f8ff',width:2.8,alpha:.86}]){target.strokeStyle=pass.color;target.lineWidth=pass.width;target.globalAlpha=pass.alpha;target.beginPath();for(const {x,y,length}of drops){target.moveTo(x,y);target.lineTo(x-length*.32,y+length);}target.stroke();}target.restore();}
if(scene.weather.includes('snow')){target.save();for(let i=0;i<230;i++){const x=r()*W,y=r()*H,radius=3+r()*5.5;target.beginPath();target.arc(x,y,radius,0,Math.PI*2);target.globalAlpha=.45;target.strokeStyle=p.ink;target.lineWidth=1.7;target.stroke();target.globalAlpha=.92;target.fillStyle=scene.palette==='monochrome'?'#ffffff':'#fffefa';target.fill();}target.restore();}
if(scene.weather.includes('fog')){for(let i=0;i<3;i++){const y=H*(.42+i*.22),g=target.createLinearGradient(0,y-150,0,y+120);g.addColorStop(0,'rgba(255,255,255,0)');g.addColorStop(.52,'rgba(255,255,255,.53)');g.addColorStop(1,'rgba(255,255,255,0)');target.fillStyle=g;target.fillRect(0,y-150,W,270);}}
target.restore();
}
function drawShootingStars(target,time=0,still=false,scene=state){if(!scene.shootingStars)return;for(let i=0;i<3;i++){const p=still||reducedMotion?[.25,.54,.8][i]:((time/6000+i*.34)%1);target.save();target.globalAlpha=Math.max(.15,Math.sin(p*Math.PI))*.9;drawSprite(target,'shooting-star',40+p*(W+150),80+p*450+i*85,155+i*22,false,palettes[scene.palette].hue,false,palettes[scene.palette].filter);target.restore();}}
function paintFrame(time=0){ctx.clearRect(0,0,W,H);if((state.shootingStars||state.items.some(x=>x.id==='shooting-star'))&&!reducedMotion)draw(ctx,state,time,false);else ctx.drawImage(stillScene,0,0);const item=activeItem();if(item){const d=dimensions(item);ctx.save();ctx.translate(item.x,item.y-d.h/2);ctx.rotate((item.rotation||0)*Math.PI/180);ctx.strokeStyle='#743251';ctx.lineWidth=4;ctx.setLineDash([10,7]);ctx.strokeRect(-d.w/2-8,-d.h/2-8,d.w+16,d.h+16);ctx.restore();}}

function animate(time){if(time-animationTime>=50){animationTime=time;paintFrame(time);}animationId=(state.shootingStars||state.items.some(x=>x.id==='shooting-star'))&&!reducedMotion&&!document.hidden?requestAnimationFrame(animate):0;}
function manageAnimation(){if(animationId)cancelAnimationFrame(animationId);animationId=0;paintFrame(animationTime);if((state.shootingStars||state.items.some(x=>x.id==='shooting-star'))&&!reducedMotion&&!document.hidden)animationId=requestAnimationFrame(animate);}
function selectionName(item){if(!item)return 'Click or tap an oddity to add it.';const name=byId[item.id].name,peers=state.items.map((value,index)=>({value,index})).filter(x=>byId[x.value.id]?.name===name).sort((a,b)=>(a.value.order??a.index)-(b.value.order??b.index)||a.index-b.index);return name+(peers.length>1?' '+(peers.findIndex(x=>x.value.uid===item.uid)+1):'');}
function updateControls(){if(!ready)return;$('#undo').disabled=busy||!undoStack.length;$('#redo').disabled=busy||!redoStack.length;$('#undo').title='Undo ('+undoStack.length+' steps available)';$('#redo').title='Redo ('+redoStack.length+' steps available)';$('#saveAlbum').disabled=busy;$('#openAlbum').disabled=busy;$('#openHistory').disabled=busy;$('#transformTools').hidden=!activeItem();$('#flipHorizontal').setAttribute('aria-pressed',String(!!activeItem()?.flip));$('#flipVertical').setAttribute('aria-pressed',String(!!activeItem()?.flipY));syncDragSurface();syncHandles();$('#selectionHint').textContent=selectionName(activeItem());}

function render(){if(!ready)return;draw(stillCtx,state);manageAnimation();$('#background').value=state.background;syncWorldPicker();$('.garden-panel').classList.toggle('void-grove',state.background==='void');document.querySelectorAll('[data-palette]').forEach(b=>{b.classList.toggle('active',b.dataset.palette===state.palette);b.setAttribute('aria-pressed',String(b.dataset.palette===state.palette));});document.querySelectorAll('[data-weather]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.weather==='clear'?!state.weather.length:state.weather.includes(b.dataset.weather))));syncSceneChoices();updateControls();queueDraft();}
function syncSceneChoices(){const weather=state.weather.length?state.weather.map(titleCaseLabel).join(' + '):'Normal',palette=palettes[state.palette].name;$('#weatherLabel').textContent=weather;$('#weatherButton').setAttribute('aria-label','Weather: '+weather);$('#weatherButton').title='Weather: '+weather;$('#paletteLabel').textContent=palette;$('#colorButton').setAttribute('aria-label','Palette: '+palette);$('#colorButton').title='Palette: '+palette;$('#backgroundButton').title='Background: '+worldLabels[state.background];}
function loadBackground(name){if(name==='none'||name==='void'||backgroundImages.has(name))return Promise.resolve();if(!backgroundNames.includes(name))return Promise.reject(Error('Unknown background'));return new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>{backgroundImages.set(name,image);resolve();};image.onerror=()=>reject(Error('This background could not load. Your creation is unchanged.'));image.src='assets/bg-'+({hell:'hell-v5','pumpkin-patch':'pumpkin-patch-v5','sandy-dunes':'sandy-dunes-v5','corn-maze':'corn-maze-v5',graveyard:'graveyard-v5','gnome-hollow':'gnome-hollow-v5','ember-river':'ember-river-v5',space:'space-v2',underwater:'underwater-v2',steampunk:'steampunk-v2',wonderland:'wonderland-v2','haunted-house':'haunted-house-v2',factory:'factory-v2'}[name]||name)+'.webp';});}
async function chooseBackground(name){if(busy)return;setBusy(true,'Loading '+worldLabels[name]+'…');try{await loadBackground(name);remember();state.background=name;render();}catch(e){notify(e.message,'error');$('#background').value=state.background;syncWorldPicker();}finally{setBusy(false);}}
function undo(){if(busy||!undoStack.length)return;redoStack.push(snapshot());state=undoStack.pop();activeUid=null;render();}
function redo(){if(busy||!redoStack.length)return;undoStack.push(snapshot());state=redoStack.pop();activeUid=null;render();}
function resizeActive(size,keepUndo=true){const item=activeItem();if(!item||busy)return;size=Math.max(40,Math.min(MAX_SIZE,size));if(item.size===size)return;if(keepUndo)remember();const center=itemCenter(item);item.size=size;item.y=Math.max(-MAX_SIZE,Math.min(H+MAX_SIZE,center.y+dimensions(item).h/2));render();}
function makePicture(scene=state){const out=document.createElement('canvas');out.width=W;out.height=H;draw(out.getContext('2d'),scene,animationTime,true);return out;}
function makeThumbnail(scene){const picture=makePicture(scene),out=document.createElement('canvas');out.width=480;out.height=432;out.getContext('2d').drawImage(picture,0,0,480,432);return out.toDataURL('image/webp',.82);}
function pictureBlob(){return new Promise((resolve,reject)=>makePicture().toBlob(blob=>blob?resolve(blob):reject(Error('The picture could not be created.')),'image/png'));}
function pictureFilename(){return 'spooky-grove-'+new Date().toISOString().replace(/[:.]/g,'-')+'-'+uid().slice(0,8)+'.png';}
function downloadBlob(blob){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=pictureFilename();document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);}
async function savePicture(){if(busy||!ready)return;try{downloadBlob(await pictureBlob());notify('Your picture is ready to download.','success');}catch(e){notify(e.message,'error');}}
async function sharePicture(){if(busy||!ready)return;try{const blob=await pictureBlob(),file=new File([blob],pictureFilename(),{type:'image/png'});if(navigator.share&&navigator.canShare?.({files:[file]})){try{await navigator.share({files:[file],title:'Spooky Grove'});}catch(e){if(e.name!=='AbortError')throw e;}}else{downloadBlob(blob);notify('This browser cannot share image files directly. Download the picture, then share it from your gallery.');}}catch{notify('Sharing did not open. Use Download, then share it from your gallery.','error');}}
async function request(path,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),20000);try{const res=await fetch(path,{credentials:'same-origin',cache:'no-store',...options,signal:controller.signal,headers:{...(options.body?{'content-type':'application/json','x-grove-request':'1'}:{}),...options.headers}});let body;try{body=await res.json();}catch{throw Error('Account storage did not respond. Your creation is unchanged.');}if(!res.ok){if(res.status===401){draftEnabled=false;accountReady=false;signedIn=false;accountChecked=true;showAccountNotice();refreshAccountGates();}const error=Error(body.error||'The request could not be completed.');error.status=res.status;throw error;}return body;}catch(error){if(error.name==='AbortError')throw Error('Account storage took too long to respond. Your creation is unchanged. Please try again.');throw error;}finally{clearTimeout(timer);}}
const activityStates=new Map();
function showActivity(key,label){activityStates.set(key,label);syncFeedback();}
function hideActivity(key){activityStates.delete(key);syncFeedback();}
function refreshAccountGates(){const guest=signedIn===false;$('#accountSignIn').hidden=!guest;for(const id of ['openAlbum','openHistory','saveAlbum','clear','randomize','favoriteFilter']){const button=$('#'+id);button.classList.toggle('requires-sign-in',guest);button.title=guest?'Sign in with ChatGPT to use this feature':id==='favoriteFilter'?(favoritesOnly?'Show All Oddities':'Show Favorite Oddities'):'';}document.querySelectorAll('.favorite-heart').forEach(button=>{button.classList.toggle('requires-sign-in',guest);button.title=guest?'Sign in to save favorites':'';});if(ready)updateControls();}
function showAccountNotice(){favorites=new Set();if(ready)renderSprites();$('#accountNotice').hidden=true;$('#accountStatus').hidden=true;}
function requireAccount(action){if(accountReady)return true;if(!accountChecked){notify('Your account is still connecting. Please try again in a moment.');return false;}if(signedIn!==false){notify('Account storage is unavailable. Your creation is unchanged.','error');return false;}$('#signInReason').textContent='Sign in with ChatGPT to '+action+'.';$('#signInDialog').showModal();return false;}
async function checkAccount(){showActivity('account','Connecting your account…');try{const data=await request('/api/session');signedIn=!!data.signedIn;const nextScope=data.draftScope||null;if(draftScope!==nextScope&&draftEnabled)draftEnabled=false;draftScope=nextScope;accountReady=signedIn&&!!data.storageReady;accountChecked=true;$('#accountStatus').textContent=signedIn&&!accountReady?'Account storage is temporarily unavailable':'';$('#accountStatus').hidden=!signedIn||accountReady;$('#accountNotice').hidden=true;if(accountReady)await loadFavorites();else if(!signedIn){favorites=new Set();renderSprites();}}catch{accountChecked=true;accountReady=false;$('#accountStatus').hidden=false;$('#accountStatus').textContent='Account storage needs attention';}finally{hideActivity('account');refreshAccountGates();}}
$('#accountSignIn').addEventListener('click',()=>{closeFloating('user');requireAccount('save your creations and favorites');});
$('#closeSignIn').addEventListener('click',()=>$('#signInDialog').close());
$('#startSignIn').addEventListener('click',e=>{try{const nonce=uid(),draft={nonce,scene:snapshot(),createdAt:Date.now()};sessionStorage.setItem('spooky-grove-sign-in-draft',JSON.stringify(draft));if(sessionStorage.getItem('spooky-grove-sign-in-draft')!==JSON.stringify(draft))throw Error();$('#startSignIn').href='/signin-with-chatgpt?return_to='+encodeURIComponent('/?grove_restore='+nonce);}catch{e.preventDefault();notify('Your creation could not be kept on this device. Download it before signing in.','error');}});
async function restoreSignInDraft(){let nonce;try{nonce=new URL(window.location.href).searchParams.get('grove_restore');if(!nonce)return;const raw=sessionStorage.getItem('spooky-grove-sign-in-draft');if(!raw)return;const draft=JSON.parse(raw);if(draft.nonce!==nonce||!Number.isFinite(draft.createdAt)||Date.now()-draft.createdAt>86400000||!draft.scene||draft.scene.version!==2||!Array.isArray(draft.scene.items)||draft.scene.items.length>100||draft.scene.items.some(x=>!byId[x.id]||typeof x.uid!=='string'||!Number.isFinite(x.x)||x.x < -3600||x.x>4800||!Number.isFinite(x.y)||x.y < -3600||x.y>4680||!Number.isFinite(x.size)||x.size<35||x.size>3600||typeof x.flip!=='boolean'||(x.rotation!==undefined&&(!Number.isFinite(x.rotation)||Math.abs(x.rotation)>180)))||!Array.isArray(draft.scene.weather)||draft.scene.weather.some(x=>!['rain','snow','fog','lightning'].includes(x))||!backgroundNames.includes(draft.scene.background)||!palettes[draft.scene.palette])return;await loadBackground(draft.scene.background);state=clone(draft.scene);selected=null;activeUid=null;undoStack=[];redoStack=[];renderSprites();render();sessionStorage.removeItem('spooky-grove-sign-in-draft');const clean=new URL(window.location.href);clean.searchParams.delete('grove_restore');window.history.replaceState(null,'',clean.pathname+clean.search+clean.hash);notify('Your grove is right where you left it.','success');return true;}catch{notify('Your sign-in draft could not be restored yet. Refresh this page to try again.','error');}}
